import unicodedata
from solution import display_width


def test_basic():
    assert display_width('abc') == 3
    assert display_width('') == 0
    assert display_width('한국') == 4


def test_fullwidth_and_emoji():
    assert display_width('ＡＢ') == 4
    assert display_width('😀') == 2


def test_combining():
    assert display_width('e\u0301') == 1
    assert display_width('a\u20dd') == 1  # enclosing mark


def test_zwj_and_format():
    assert display_width('\u200d') == 0
    assert display_width('a\u200bb') == 2
    assert display_width('\ufeff') == 0


def test_wide_combining_conflict():
    bad = []
    for cp in range(0x110000):
        c = chr(cp)
        if unicodedata.category(c) in ('Mn', 'Me', 'Cf') and unicodedata.east_asian_width(c) in ('W', 'F'):
            bad.append(c)
    for c in bad:
        assert display_width(c) == 0, hex(ord(c))


def test_specific_tone_marks():
    for c in '\u302a\u302b\u302c\u302d\u3099\u309a':
        if unicodedata.category(c) in ('Mn', 'Me', 'Cf'):
            assert display_width(c) == 0


def test_family_emoji_zwj():
    s = '👨\u200d👩\u200d👧'
    assert display_width(s) == 6


def test_control_and_other():
    assert display_width('\u00a0') == 1
    assert display_width('ｱ') == 1  # halfwidth katakana

from solution import display_width
import unicodedata


def test_empty():
    assert display_width('') == 0


def test_ascii():
    assert display_width('abc') == 3


def test_hangul():
    assert display_width('한국') == 4


def test_cjk():
    assert display_width('中文') == 4


def test_fullwidth_letters():
    assert display_width('ＡＢ') == 4


def test_combining_mn():
    assert display_width('e\u0301') == 1


def test_enclosing_me():
    assert display_width('a\u20dd') == 1


def test_zwj():
    assert display_width('a\u200db') == 2


def test_emoji_wide():
    assert display_width('😀') == 2


def test_zwj_sequence():
    # man ZWJ woman: 2 + 0 + 2
    assert display_width('👨\u200d👩') == 4


def test_mc_spacing_mark_is_one():
    # Devanagari sign visarga is Mc -> 1 column
    assert unicodedata.category('\u0903') == 'Mc'
    assert display_width('\u0903') == 1


def test_halfwidth_katakana():
    assert display_width('ｱ') == 1


def test_space_and_mixed():
    assert display_width('a 한') == 4


def test_soft_hyphen_cf():
    assert display_width('\u00ad') == 0


def test_control_char_one():
    # Cc is not listed as zero width, so "everything else" -> 1
    assert display_width('\n') == 1


def test_combining_on_wide():
    assert display_width('한\u0301') == 2


def test_variation_selector_mn():
    assert display_width('\ufe0f') == 0


def test_ambiguous_is_one():
    assert display_width('±') == 1
